-- Table structure and data for `tbl_shifts`
DROP TABLE IF EXISTS `tbl_shifts`;
CREATE TABLE `tbl_shifts` (
  `shift_id` int(11) NOT NULL AUTO_INCREMENT,
  `cashier_id` int(11) NOT NULL,
  `starting_cash` decimal(10,2) NOT NULL DEFAULT 0.00,
  `start_time` datetime NOT NULL DEFAULT current_timestamp(),
  `end_time` datetime DEFAULT NULL,
  `expected_cash` decimal(10,2) DEFAULT NULL,
  `actual_cash` decimal(10,2) DEFAULT NULL,
  `short_over` decimal(10,2) DEFAULT NULL,
  `status` enum('open','closed') NOT NULL DEFAULT 'open',
  PRIMARY KEY (`shift_id`),
  KEY `fk_shift_cashier` (`cashier_id`),
  CONSTRAINT `fk_shift_cashier` FOREIGN KEY (`cashier_id`) REFERENCES `tbl_users` (`user_id`) ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

