DROP TABLE IF EXISTS `tbl_transaction_details`;
CREATE TABLE `tbl_transaction_details` (
  `detail_id` int(11) NOT NULL AUTO_INCREMENT,
  `transaction_id` int(11) NOT NULL,
  `item_id` int(11) NOT NULL,
  `quantity` decimal(10,2) NOT NULL DEFAULT 1.00,
  `unit_price` decimal(10,2) NOT NULL DEFAULT 0.00,
  `subtotal` decimal(10,2) NOT NULL DEFAULT 0.00,
  PRIMARY KEY (`detail_id`),
  KEY `fk_det_txn` (`transaction_id`),
  KEY `fk_det_item` (`item_id`),
  CONSTRAINT `fk_det_item` FOREIGN KEY (`item_id`) REFERENCES `tbl_inventory` (`item_id`) ON UPDATE CASCADE,
  CONSTRAINT `fk_det_txn` FOREIGN KEY (`transaction_id`) REFERENCES `tbl_transactions` (`transaction_id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

